#pragma once
inline int se_hex_digit(unsigned char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;throw std::runtime_error("Invalid hex digit.");}
inline std::string se_encoding_hex(const std::string& value){static constexpr char digits[]="0123456789abcdef";std::string out;for(unsigned char c:value){out+=digits[c>>4];out+=digits[c&15];}return out;}
inline std::string se_encoding_unhex(const std::string& value){if(value.size()%2)throw std::runtime_error("Hex needs an even number of digits.");std::string out;for(std::size_t i=0;i<value.size();i+=2)out+=static_cast<char>((se_hex_digit(value[i])<<4)|se_hex_digit(value[i+1]));return out;}
inline bool se_encoding_utf8_valid(const std::string& text){for(std::size_t i=0;i<text.size();){unsigned char c=text[i];std::size_t n=c<0x80?1:(c>=0xc2&&c<=0xdf?2:(c>=0xe0&&c<=0xef?3:(c>=0xf0&&c<=0xf4?4:0)));if(n==0||n>text.size()-i)return false;for(std::size_t k=1;k<n;++k)if((static_cast<unsigned char>(text[i+k])&0xc0)!=0x80)return false;if(n>1){unsigned char next=text[i+1];if((c==0xe0&&next<0xa0)||(c==0xed&&next>=0xa0)||(c==0xf0&&next<0x90)||(c==0xf4&&next>=0x90))return false;}i+=n;}return true;}
inline std::string se_url_encode(const std::string& text){static constexpr char digits[]="0123456789ABCDEF";std::string out;for(unsigned char c:text){if((c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||c=='-'||c=='_'||c=='.'||c=='~')out+=c;else{out+='%';out+=digits[c>>4];out+=digits[c&15];}}return out;}
inline std::string se_url_decode(const std::string& text){std::string out;for(std::size_t i=0;i<text.size();++i){if(text[i]!='%'){out+=text[i];continue;}if(text.size()-i<3)throw std::runtime_error("Incomplete percent escape.");out+=static_cast<char>((se_hex_digit(text[i+1])<<4)|se_hex_digit(text[i+2]));i+=2;}return out;}
inline std::string se_url_query(const SEMap<std::string>& values){std::string out;for(const auto& [key,value]:values.items){if(!out.empty())out+='&';out+=se_url_encode(key)+"="+se_url_encode(value);}return out;}
inline SEMap<std::string> se_url_parse_query(std::string text){if(!text.empty()&&text.front()=='?')text.erase(0,1);SEMap<std::string> out;std::istringstream stream(text);std::string part;while(std::getline(stream,part,'&')){if(part.empty())continue;auto eq=part.find('=');auto key=se_url_decode(part.substr(0,eq));auto value=eq==std::string::npos?"":se_url_decode(part.substr(eq+1));std::replace(key.begin(),key.end(),'+',' ');std::replace(value.begin(),value.end(),'+',' ');out.items.emplace_back(key,value);}return out;}
